class Spacecraft {
  #fuelLevel;

  constructor(name) {
    this.name = name;
    this.#fuelLevel = 100; // Initial fuel
  }

  getFuelLevel() {
    return this.#fuelLevel;
  }

  refuel(amount) {
    if (amount > 0) {
      this.#fuelLevel += amount;
      return `${this.name} refueled by ${amount}. Current fuel: ${this.#fuelLevel}`;
    }
    return "Refuel amount must be positive.";
  }

  fly(distance) {
    if (distance > 0 && this.#fuelLevel >= distance) {
      this.#fuelLevel -= distance;
      return `${this.name} flew ${distance} units. Remaining fuel: ${this.#fuelLevel}`;
    } else if (distance <= 0) {
      return "Flight distance must be positive.";
    } else {
      return `Not enough fuel for ${this.name} to fly ${distance} units. Current fuel: ${this.#fuelLevel}`;
    }
  }
}

// --- Test your code ---
const voyager = new Spacecraft('Voyager 1');
console.log(`Initial fuel for ${voyager.name}: ${voyager.getFuelLevel()}`);
voyager.refuel(50);
console.log(`Fuel after refuel: ${voyager.getFuelLevel()}`);
console.log(voyager.fly(80));
console.log(`Fuel after flying: ${voyager.getFuelLevel()}`);
console.log(voyager.fly(100));
console.log(`Fuel after attempted flight: ${voyager.getFuelLevel()}`);

